import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const Cart = () => {
  const [cartItems, setCartItems] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const cart = JSON.parse(sessionStorage.getItem("cart")) || [];
    setCartItems(cart);
  }, []);

  const removeItem = (id) => {
    const updated = cartItems.filter((item) => item.listing_id !== id);
    setCartItems(updated);
    sessionStorage.setItem("cart", JSON.stringify(updated));
  };

  const subtotal = cartItems.reduce((sum, item) => sum + parseFloat(item.price), 0);
  const tax = subtotal * 0.08;
  const shipping = Math.floor(Math.random() * 5) + 3;
  const total = (subtotal + tax + shipping).toFixed(2);

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar />
      <div className="p-4 flex-grow">
        <h2 className="text-xl font-bold mb-4">Your Cart</h2>
        {cartItems.map((item) => (
          <div key={item.listing_id} className="border p-2 mb-2">
            <h3>{item.title}</h3>
            <p>${item.price}</p>
            <button onClick={() => removeItem(item.listing_id)}>Remove</button>
          </div>
        ))}
        <div className="mt-4">
          <p>Subtotal: ${subtotal.toFixed(2)}</p>
          <p>Tax: ${tax.toFixed(2)}</p>
          <p>Shipping: ${shipping}</p>
          <p className="font-bold">Total: ${total}</p>
          <button className="mt-2 bg-blue-500 text-white px-4 py-2" onClick={() => navigate("/checkout")}>
            Proceed to Checkout
          </button>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Cart;
